[
  {
    "statement": "There is no data on the cost-effectiveness of different methods for establishing native forbs.",
    "citations": []
  },
  {
    "statement": "Several methods have been studied for their effectiveness in establishing vegetation.",
    "citations": []
  },
  {
    "statement": "Sowing native grass and forb seeds has been shown to increase the richness of forb species in 71% of cases in one UK study.",
    "citations": [
      "3432"
    ]
  },
  {
    "statement": "Three out of four studies in the Czech Republic and the USA found that sowing native grass and forb seeds increased the cover or density of forb species.",
    "citations": [
      "3432"
    ]
  },
  {
    "statement": "A study in the USA found that sowing seeds at a higher density also increased forb species richness and cover.",
    "citations": [
      "3405"
    ]
  },
  {
    "statement": "Using an organic blanket after sowing seeds was found to increase overall plant species richness in a study in Spain.",
    "citations": [
      "3431"
    ]
  },
  {
    "statement": "Methods shown to be effective in establishing forbs and other vegetation do not have associated cost information in the provided documents.",
    "citations": []
  }
]

[
  {
    "statement": "Sowing native grass and forb seeds has been shown to increase overall plant species richness.",
    "citations": [
      "3432"
    ]
  },
  {
    "statement": "Sowing native grass and forb seeds has been shown to increase the richness of forbs and sown species.",
    "citations": [
      "3432"
    ]
  },
  {
    "statement": "Sowing native grass and forb seeds was found to increase the abundance of sown species in most cases.",
    "citations": [
      "3432"
    ]
  },
  {
    "statement": "One study found that sowing native grass and forb seeds increased the cover of forb species.",
    "citations": [
      "3432"
    ]
  },
  {
    "statement": "One study found that sowing native grass and forb seeds increased the density of forb species.",
    "citations": [
      "3432"
    ]
  },
  {
    "statement": "Actions that enhance floral resources have a positive impact on pollinators.",
    "citations": []
  },
  {
    "statement": "One study found that planting flower strips resulted in more wild bee species.",
    "citations": [
      "1406"
    ]
  },
  {
    "statement": "One study found that planting flower strips resulted in more wild bee individuals.",
    "citations": [
      "1406"
    ]
  },
  {
    "statement": "The average abundance of long-tongued bumblebees was positively correlated with the number of ‘pollen and nectar’ agri-environment agreements in the area.",
    "citations": [
      "362"
    ]
  },
  {
    "statement": "Some planted flower species have been found to be more attractive to pollinators than others.",
    "citations": [
      "1406"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects of burning vegetation before seeding or planting on grassland vegetation.",
    "citations": [
      "3417"
    ]
  },
  {
    "statement": "One replicated, controlled study in the UK found that applying herbicide before sowing seeds increased sown species richness.",
    "citations": [
      "3418"
    ]
  },
  {
    "statement": "A replicated, controlled study in the UK or Belgium found that removing vegetation before sowing seeds increased the germination rate of sown species.",
    "citations": [
      "3416"
    ]
  },
  {
    "statement": "A separate replicated, controlled study in the UK or Belgium found that removing vegetation and leaf litter before sowing seeds increased the number of seedlings for one of three species.",
    "citations": [
      "3416"
    ]
  }
]

[
  {
    "statement": "A study in the USA found that inoculating soil with mycorrhizal fungi before sowing seeds initially increased vegetation cover.",
    "citations": [
      "3429"
    ]
  },
  {
    "statement": "After three years, there was no difference in vegetation cover between areas inoculated with mycorrhizal fungi and uninoculated areas.",
    "citations": [
      "3429"
    ]
  },
  {
    "statement": "A controlled study in the USA found that adding soil microbes and nutrients when planting grass plugs did not change the overall cover of herbaceous species.",
    "citations": [
      "3429"
    ]
  },
  {
    "statement": "A study in Iceland that involved adding fertilizer and sowing seeds found an increase in vegetation cover in two of three cases.",
    "citations": [
      "1704"
    ]
  },
  {
    "statement": "A study in a bog in New Zealand reported that fertilizing typically increased total vegetation cover.",
    "citations": [
      "1812"
    ]
  },
  {
    "statement": "A study in a bog in Canada found that fertilizer increased total vegetation, vascular plant and bryophyte cover.",
    "citations": [
      "1826"
    ]
  },
  {
    "statement": "A separate study in a bog in Canada found that fertilizer increased sedge cover but had no effect on total vegetation cover.",
    "citations": [
      "1826"
    ]
  },
  {
    "statement": "Another study in a bog in New Zealand reported that fertilizer typically increased the cover of a sown shrub and rush.",
    "citations": [
      "1826"
    ]
  },
  {
    "statement": "The increase in the cover of a sown shrub and rush from fertilizer was dependent on the chemical in the fertilizer and preparation of the peat.",
    "citations": [
      "1826"
    ]
  }
]
